import{defineConfig}from'vite'
import react from'@vitejs/plugin-react'
export default defineConfig({plugins:[react()],build:{outDir:'dist'}})

import { useEffect, useState } from 'react'
const OR='#F56600', PU='#522D80', ink='#0B1220', mut='#5B6472', bg='#F6F7F9', card='#fff', bd='#E6E8EC'
const rates={GSP:{n:'Greenville-Spartanburg',t:75},CLT:{n:'Charlotte Douglas',t:175}}
const nav=(p,q={})=>{const s=new URLSearchParams(q).toString();location.hash=s?`#/${p}?${s}`:`#/${p}`}
const route=()=>{const r=(location.hash.replace(/^#\/?/,'')||'landing').split('?');return{path:r[0],params:Object.fromEntries(new URLSearchParams(r[1]||''))}}
const Btn=({children:c,onClick,v='o',dis})=>{const bg=v==='p'?PU:v==='g'?`linear-gradient(135deg,${PU},${OR})`:OR;return <button disabled={dis} onClick={onClick} className="pressable" style={{width:'100%',padding:'14px 20px',borderRadius:14,background:bg,color:'#fff',fontWeight:600,fontSize:17,opacity:dis?.5:1,boxShadow:'0 2px 8px rgba(0,0,0,.08)'}}>{c}</button>}
const Tabs=({a,on})=> <nav style={{position:'sticky',bottom:0,display:'grid',gridTemplateColumns:'repeat(4,1fr)',background:'rgba(255,255,255,.92)',backdropFilter:'blur(16px)',borderTop:`1px solid ${bd}`,paddingBottom:'var(--safe-bottom)'}}>{[['home','Rides','🚗'],['schedule','Schedule','📅'],['friends','Friends','👥'],['account','Account','👤']].map(([id,l,i])=><button key={id} onClick={()=>on(id)} style={{padding:'10px 4px 12px',display:'flex',flexDirection:'column',alignItems:'center',gap:2,color:a===id?OR:mut,fontWeight:a===id?600:500,fontSize:11}}><span style={{fontSize:20}}>{i}</span>{l}</button>)}</nav>
const Map=({h=150,heat})=><div style={{height:h,borderRadius:h==='100%'?0:16,background:'linear-gradient(160deg,#e8eef5,#c9d2df)',display:'grid',placeItems:'center',position:h==='100%'?'absolute':'relative',inset:h==='100%'?0:undefined,width:'100%',overflow:'hidden'}}>{heat&&<><div style={{position:'absolute',width:120,height:120,borderRadius:'50%',background:'rgba(82,45,128,.22)',left:'30%',top:'35%'}}/><div style={{position:'absolute',width:90,height:90,borderRadius:'50%',background:'rgba(245,102,0,.16)',left:'48%',top:'48%'}}/></>}<div style={{width:18,height:18,borderRadius:'50%',background:OR,border:'3px solid #fff',boxShadow:'0 2px 8px rgba(0,0,0,.25)',zIndex:1}}/><div style={{position:'absolute',bottom:8,left:8,fontSize:11,color:mut,background:'rgba(255,255,255,.9)',padding:'4px 8px',borderRadius:8}}>Clemson · map</div></div>
function Landing(){return <div className="fade-in" style={{minHeight:'100%',background:card}}><header style={{height:280,background:`linear-gradient(180deg,rgba(11,18,32,.15),rgba(82,45,128,.55) 55%,rgba(11,18,32,.85)),linear-gradient(135deg,${OR},${PU} 60%,#1a0f2e)`,color:'#fff',padding:'28px 24px 32px',display:'flex',flexDirection:'column',justifyContent:'flex-end'}}><div style={{fontSize:13,letterSpacing:2,fontWeight:600,opacity:.9,marginBottom:8}}>RIDE · GAME · REPEAT</div><h1 style={{fontSize:36,fontWeight:700,letterSpacing:-.8}}><span style={{color:'#FFB370'}}>Clemson</span> <span style={{color:'#E8D5FF'}}>RIDES</span></h1><div style={{marginTop:12,alignSelf:'flex-start',padding:'6px 12px',borderRadius:999,background:'rgba(255,255,255,.15)',border:'1px solid rgba(255,255,255,.25)',fontSize:12,fontWeight:700,letterSpacing:.8}}>TIGERS GET YOU THERE</div></header><div style={{padding:28}}><h2 style={{fontSize:22,fontWeight:600,marginBottom:10}}>Clemson-only airport rides</h2><p style={{color:mut,fontSize:15,lineHeight:1.45,marginBottom:20}}>Flat rates to GSP ($75) & CLT ($175). Skip the surge on game day.</p><div style={{display:'flex',flexDirection:'column',gap:10,marginBottom:28}}><Btn onClick={()=>nav('home')}>Open rider app</Btn><Btn v="p" onClick={()=>nav('driver')}>Driver mode</Btn></div><div style={{background:bg,borderRadius:20,padding:24,border:`1px solid ${bd}`,textAlign:'center'}}><h3 style={{fontSize:17,fontWeight:600,marginBottom:6}}>Get the native apps</h3><p style={{fontSize:13,color:mut,marginBottom:20}}>QR placeholders · Expo EAS coming soon</p><div style={{display:'flex',justifyContent:'center',gap:36}}>{['iOS App Store','Google Play'].map(l=><div key={l}><div style={{width:120,height:120,borderRadius:16,background:'repeating-conic-gradient(#0B1220 0% 25%,#fff 0% 50%) 0 0/12px 12px',border:`2px solid ${bd}`,margin:'0 auto 8px',display:'grid',placeItems:'center'}}><div style={{background:'#fff',padding:8,borderRadius:8,fontWeight:700,fontSize:11,color:PU}}>QR</div></div><div style={{fontSize:13,fontWeight:600,color:mut}}>{l}</div></div>)}</div></div></div></div>}
function Home(){const[q,setQ]=useState('');const go=d=>nav('confirm',{dest:d||q||'GSP Airport'});return <div style={{display:'flex',flexDirection:'column',minHeight:'100%',background:bg}}><div style={{flex:1,overflowY:'auto'}}><header style={{height:200,background:`linear-gradient(180deg,rgba(11,18,32,.05),rgba(82,45,128,.45) 50%,rgba(11,18,32,.88)),linear-gradient(120deg,#c45a12,${PU} 70%)`,color:'#fff',padding:20,display:'flex',flexDirection:'column',justifyContent:'flex-end',position:'relative'}}><div style={{position:'absolute',top:16,right:16,opacity:.18,fontSize:72}}>🐾</div><div style={{fontSize:11,letterSpacing:2.2,fontWeight:600,opacity:.85,marginBottom:6}}>RIDE · GAME · REPEAT</div><div style={{fontSize:26,fontWeight:700}}><span style={{color:'#FFB370'}}>Clemson</span> <span style={{color:'#E8D5FF'}}>RIDES</span></div><div style={{marginTop:8,alignSelf:'flex-start',padding:'4px 10px',borderRadius:999,background:'rgba(255,255,255,.14)',fontSize:10,fontWeight:700,letterSpacing:.7}}>TIGERS GET YOU THERE</div></header><div style={{padding:20}}><h1 style={{fontSize:24,fontWeight:600}}>Welcome, John</h1><p style={{color:mut,fontSize:15,margin:'4px 0 16px'}}>Where are you headed, Tiger?</p><div style={{display:'flex',alignItems:'center',gap:12,padding:'14px 16px',background:card,borderRadius:16,border:`2px solid ${OR}`,boxShadow:'0 4px 16px rgba(245,102,0,.12)'}}><span>🔍</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Where are you going?" style={{flex:1,border:'none',outline:'none',background:'transparent',fontSize:16,fontWeight:500}}/></div><button className="pressable" onClick={()=>go()} style={{width:'100%',padding:10,fontSize:13,fontWeight:600,color:OR,marginTop:8}}>Search destination →</button><div style={{display:'flex',gap:10,marginTop:8,overflowX:'auto'}}><button className="pressable" onClick={()=>nav('schedule')} style={{padding:'10px 16px',borderRadius:999,background:card,color:OR,border:'1.5px solid rgba(245,102,0,.35)',fontWeight:600,fontSize:14,boxShadow:'0 2px 8px rgba(0,0,0,.08)'}}>⏰ Schedule a ride</button><button className="pressable" onClick={()=>nav('friends')} style={{padding:'10px 16px',borderRadius:999,background:card,color:PU,border:'1.5px solid rgba(82,45,128,.35)',fontWeight:600,fontSize:14}}>👥 Ride with friends</button></div><div style={{display:'flex',gap:10,marginTop:18,overflowX:'auto'}}>{[['🏠','Home','Simpsonville'],['🎓','Clemson University','Sikes Hall'],['💼','Work','Saved place']].map(([i,l,s])=><button key={l} className="pressable" onClick={()=>go(s)} style={{flex:'0 0 auto',minWidth:118,padding:14,borderRadius:16,background:card,boxShadow:'0 2px 8px rgba(0,0,0,.08)',border:`1px solid ${bd}`,textAlign:'left'}}><div style={{fontSize:22,marginBottom:8}}>{i}</div><div style={{fontWeight:600,fontSize:13}}>{l}</div><div style={{fontSize:11,color:'#8B939E',marginTop:2}}>{s}</div></button>)}</div><div style={{marginTop:20,background:card,borderRadius:18,padding:12,boxShadow:'0 8px 28px rgba(11,18,32,.1)',border:`1px solid ${bd}`}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8,padding:'0 4px'}}><span style={{fontWeight:600,fontSize:15}}>You are here</span><span style={{fontSize:12,color:mut}}>Memorial Stadium</span></div><Map h={150}/></div><div style={{margin:'16px 0',borderRadius:18,padding:16,background:card,border:`1px solid ${bd}`,display:'flex',gap:14,alignItems:'center'}}><div style={{width:48,height:48,borderRadius:14,background:'#FFF4EC',display:'grid',placeItems:'center',fontSize:24}}>🏈</div><div style={{flex:1}}><div style={{fontWeight:700,fontSize:15}}>Game Day Rides</div><div style={{fontSize:13,color:mut,marginTop:2}}>Skip the surge. Book ahead!</div></div><button className="pressable" onClick={()=>nav('schedule')} style={{padding:'10px 14px',borderRadius:12,background:`linear-gradient(135deg,${PU},${OR})`,color:'#fff',fontWeight:600,fontSize:13}}>Schedule Now</button></div></div></div><Tabs a="home" on={id=>nav(id==='home'?'home':id)}/></div>}
function Confirm({dest='GSP Airport'}){const[addr,setAddr]=useState('Memorial Stadium · Lot 5');const[note,setNote]=useState('');return <div className="fade-in" style={{display:'flex',flexDirection:'column',height:'100%',background:bg}}><div style={{padding:'16px 20px 8px',display:'flex',alignItems:'center',gap:12}}><button onClick={()=>nav('home')} style={{fontSize:20}}>←</button><h1 style={{fontSize:20,fontWeight:600}}>Confirm pickup spot</h1></div><div style={{padding:'0 16px'}}><Map h={260}/><p style={{fontSize:12,color:'#8B939E',marginTop:8,textAlign:'center'}}>Adjust pin · map stub</p></div><div style={{marginTop:'auto',background:card,borderRadius:'24px 24px 0 0',padding:'12px 20px 28px',boxShadow:'0 8px 28px rgba(11,18,32,.1)'}}><div style={{width:40,height:4,borderRadius:2,background:bd,margin:'0 auto 16px'}}/><label style={{fontSize:13,fontWeight:600,color:mut}}>Pickup address</label><input value={addr} onChange={e=>setAddr(e.target.value)} style={{width:'100%',marginTop:6,padding:'12px 14px',borderRadius:12,border:`1px solid ${bd}`,background:bg,marginBottom:14}}/><label style={{fontSize:13,fontWeight:600,color:mut}}>Note for driver</label><textarea value={note} onChange={e=>setNote(e.target.value)} rows={2} placeholder="Near orange gates…" style={{width:'100%',marginTop:6,padding:'12px 14px',borderRadius:12,border:`1px solid ${bd}`,background:bg,resize:'none',marginBottom:8}}/><p style={{fontSize:13,color:mut,marginBottom:14}}>Going to <strong>{dest}</strong></p><Btn onClick={()=>nav('tiers',{dest,pickup:addr})}>Confirm and request</Btn></div></div>}
const TIERS=[{id:'standard',n:'Standard',i:'🚗',eta:'4 min',m:'4 seats',p:18.5},{id:'wait',n:'Wait & Save',i:'⏱️',eta:'12 min',m:'Save ~20%',p:14.2},{id:'comfort',n:'Extra Comfort',i:'✨',eta:'6 min',m:'Newer cars',p:23},{id:'xl',n:'XL',i:'🚐',eta:'8 min',m:'6 seats',p:28.75},{id:'pet',n:'Pet',i:'🐾',eta:'9 min',m:'Pet-friendly',p:21},{id:'tesla',n:'Self-Driving Tesla Model 3',i:'⚡',eta:'7 min',m:'Premium',p:36,prem:1,badge:'TESLA'}]
function Tiers({dest='1900 GSP Dr'}){const[sel,setSel]=useState(TIERS[0]);const[up,setUp]=useState(null);const go=()=>{if(sel.id==='standard')return setUp('comfort');if(sel.id==='comfort')return setUp('tesla');alert(`Requested ${sel.n} — stub`);nav('home')};return <div className="fade-in" style={{display:'flex',flexDirection:'column',height:'100%',background:bg}}><div style={{padding:'12px 16px 0'}}><button onClick={()=>nav('confirm',{dest})} style={{fontSize:20,marginBottom:8}}>←</button><Map h={140}/><div style={{marginTop:10,padding:'8px 12px',borderRadius:999,background:'#F3EEF8',color:PU,fontSize:12,fontWeight:600,display:'inline-flex'}}>🐯 Clemson student promo · 10% off</div><p style={{marginTop:8,fontSize:13,color:mut}}>To <strong style={{color:ink}}>{dest}</strong></p></div><div style={{flex:1,marginTop:12,background:card,borderRadius:'24px 24px 0 0',padding:'8px 12px 20px',boxShadow:'0 8px 28px rgba(11,18,32,.1)',overflowY:'auto',display:'flex',flexDirection:'column'}}><div style={{width:40,height:4,borderRadius:2,background:bd,margin:'4px auto 10px'}}/>{TIERS.map(t=><button key={t.id} className="pressable" onClick={()=>setSel(t)} style={{display:'flex',alignItems:'center',gap:14,width:'100%',padding:'14px 12px',borderRadius:14,background:sel.id===t.id?'#FFF4EC':'transparent',border:sel.id===t.id?'1.5px solid rgba(245,102,0,.35)':'1.5px solid transparent',textAlign:'left'}}><div style={{width:48,height:48,borderRadius:12,background:t.prem?'#F3EEF8':bg,display:'grid',placeItems:'center',fontSize:24}}>{t.i}</div><div style={{flex:1}}><div style={{fontWeight:600,fontSize:16}}>{t.n}{t.badge&&<span style={{marginLeft:8,fontSize:10,fontWeight:700,color:PU,background:'#F3EEF8',padding:'2px 7px',borderRadius:999}}>{t.badge}</span>}</div><div style={{color:mut,fontSize:13,marginTop:2}}>{t.eta} · {t.m}</div></div><div style={{fontWeight:600,fontSize:17}}>${t.p.toFixed(2)}</div></button>)}<div style={{padding:'12px 8px 0'}}><Btn v={sel.prem?'p':'o'} onClick={go}>Select {sel.id==='tesla'?'Tesla':sel.n}</Btn></div></div>{up&&<div style={{position:'fixed',inset:0,zIndex:100,background:'rgba(11,18,32,.45)',display:'grid',placeItems:'center',padding:20}} onClick={()=>{setUp(null);alert('Requested — stub');nav('home')}}><div className="fade-in" onClick={e=>e.stopPropagation()} style={{width:'100%',maxWidth:360,background:card,borderRadius:24,padding:24,boxShadow:'0 8px 28px rgba(11,18,32,.1)'}}><div style={{height:140,borderRadius:16,background:up==='tesla'?'linear-gradient(135deg,#F3EEF8,#E8E0F0)':'linear-gradient(135deg,#FFF4EC,#F3EEF8)',display:'grid',placeItems:'center',fontSize:56,marginBottom:18}}>{up==='tesla'?'🚗':'✨'}</div><h2 style={{fontSize:22,fontWeight:600,marginBottom:8}}>{up==='tesla'?'Upgrade to Tesla Model 3':'Ride in Extra Comfort'}</h2><p style={{color:mut,fontSize:15,marginBottom:22}}>{up==='tesla'?'Premium self-driving capable.':'Upgrade and treat yourself.'}</p><Btn v={up==='tesla'?'p':'o'} onClick={()=>{setSel(TIERS.find(x=>x.id===up));setUp(null)}}>Upgrade for ${up==='tesla'?'13.00':'4.50'} more</Btn><button onClick={()=>{setUp(null);alert('Requested — stub');nav('home')}} style={{width:'100%',marginTop:12,padding:12,fontWeight:600,color:mut}}>Not now</button></div></div>}</div>}
function Schedule(){const[ap,setAp]=useState('GSP');const[busy,setBusy]=useState(false);const[res,setRes]=useState(null);const tot=rates[ap].t;const dep=Math.round(tot*.25*100)/100;const book=async()=>{setBusy(true);console.log('[Stripe stub]',{ap,dep});setRes({clientSecret:'pi_stub_clemson_deposit',dep});setBusy(false)};return <div style={{display:'flex',flexDirection:'column',minHeight:'100%',background:bg}}><div style={{flex:1,padding:20,overflowY:'auto'}}><button onClick={()=>nav('home')} style={{fontSize:20,marginBottom:12}}>←</button><h1 style={{fontSize:24,fontWeight:600}}>Schedule airport</h1><p style={{color:mut,fontSize:14,margin:'6px 0 20px'}}>Flat rates · 25% deposit holds your ride</p><div style={{display:'flex',gap:10,marginBottom:20}}>{Object.entries(rates).map(([c,r])=><button key={c} className="pressable" onClick={()=>setAp(c)} style={{flex:1,padding:16,borderRadius:16,background:ap===c?'#FFF4EC':card,border:`1.5px solid ${ap===c?'rgba(245,102,0,.4)':bd}`,textAlign:'left',boxShadow:'0 2px 8px rgba(0,0,0,.08)'}}><div style={{fontWeight:700,fontSize:18}}>{c}</div><div style={{fontSize:12,color:mut,marginTop:4}}>{r.n}</div><div style={{fontWeight:600,fontSize:20,marginTop:10,color:OR}}>${r.t}</div></button>)}</div><label style={{fontSize:13,fontWeight:600,color:mut}}>Date</label><input type="date" style={{width:'100%',margin:'6px 0 14px',padding:'12px 14px',borderRadius:12,border:`1px solid ${bd}`,background:card}}/><label style={{fontSize:13,fontWeight:600,color:mut}}>Pickup time</label><input type="time" style={{width:'100%',margin:'6px 0 20px',padding:'12px 14px',borderRadius:12,border:`1px solid ${bd}`,background:card}}/><div style={{background:card,borderRadius:18,padding:18,border:`1px solid ${bd}`,marginBottom:20}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{color:mut}}>Trip total</span><span style={{fontWeight:600}}>${tot.toFixed(2)}</span></div><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{color:mut}}>Deposit (25%)</span><span style={{fontWeight:700,color:PU,fontSize:18}}>${dep.toFixed(2)}</span></div><div style={{fontSize:12,color:'#8B939E'}}>Stripe PaymentIntent stub</div></div><Btn v="g" dis={busy} onClick={book}>{busy?'Creating…':`Pay $${dep.toFixed(2)} deposit`}</Btn>{res&&<div style={{marginTop:16,padding:14,borderRadius:14,background:'#F3EEF8',fontSize:13,color:PU}}>✓ Deposit stubbed · {res.clientSecret}</div>}</div><Tabs a="schedule" on={id=>nav(id==='home'?'home':id)}/></div>}
function Driver(){const[pri,setPri]=useState(false);const[offer,setOffer]=useState(false);return <div style={{position:'relative',height:'100%',background:'#e8eaed'}}><Map h="100%" heat/><div style={{position:'absolute',top:16,left:16,right:16,display:'flex',justifyContent:'space-between',zIndex:20}}><button onClick={()=>nav('landing')} style={{width:44,height:44,borderRadius:'50%',background:'rgba(255,255,255,.95)',boxShadow:'0 2px 8px rgba(0,0,0,.08)',fontSize:18}}>☰</button><div style={{padding:'10px 18px',borderRadius:999,background:'rgba(255,255,255,.95)',fontWeight:700,fontSize:17,boxShadow:'0 2px 8px rgba(0,0,0,.08)'}}>$0.00</div><button onClick={()=>setOffer(true)} style={{width:44,height:44,borderRadius:'50%',background:'rgba(255,255,255,.95)',boxShadow:'0 2px 8px rgba(0,0,0,.08)',fontSize:18}}>🔔</button></div>{!offer&&<div style={{position:'absolute',left:0,right:0,bottom:0,zIndex:20,background:card,borderRadius:'24px 24px 0 0',padding:'12px 20px calc(20px + var(--safe-bottom))',boxShadow:'0 8px 28px rgba(11,18,32,.1)'}}><div style={{width:40,height:4,borderRadius:2,background:bd,margin:'0 auto 14px'}}/><div style={{display:'flex',alignItems:'center',gap:10,marginBottom:16}}><span style={{width:10,height:10,borderRadius:'50%',background:'#1F8A4C'}}/><span style={{fontWeight:600,fontSize:18}}>You're online</span></div><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'12px 0',borderTop:`1px solid ${bd}`}}><div><div style={{fontWeight:600}}>Priority Mode</div><div style={{fontSize:12,color:mut}}>Higher-value rides first</div></div><button onClick={()=>setPri(p=>!p)} style={{width:52,height:30,borderRadius:999,background:pri?PU:bd,position:'relative'}}><span style={{position:'absolute',top:3,left:pri?24:3,width:24,height:24,borderRadius:'50%',background:'#fff',transition:'left 200ms'}}/></button></div><div style={{padding:'12px 0 4px',borderTop:`1px solid ${bd}`}}><div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}><span style={{fontWeight:600}}>Unlock Silver</span><span style={{fontSize:13,color:mut}}>2/4</span></div><div style={{height:8,borderRadius:999,background:bg,overflow:'hidden'}}><div style={{width:'50%',height:'100%',background:OR,borderRadius:999}}/></div><p style={{fontSize:12,color:'#8B939E',marginTop:8}}>Complete 2 more trips for Silver perks</p></div><button onClick={()=>setOffer(true)} style={{marginTop:12,width:'100%',padding:10,fontSize:13,color:PU,fontWeight:600}}>Simulate incoming ride →</button></div>}{offer&&<div style={{position:'absolute',left:0,right:0,bottom:0,zIndex:30,background:card,borderRadius:'24px 24px 0 0',padding:'12px 20px calc(24px + var(--safe-bottom))',boxShadow:'0 8px 28px rgba(11,18,32,.1)'}}><div style={{width:40,height:4,borderRadius:2,background:bd,margin:'0 auto 14px'}}/><div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline'}}><div style={{fontSize:32,fontWeight:700}}>$22.40</div><div style={{fontSize:13,color:mut}}>~$38/hr est.</div></div><div style={{marginTop:14,display:'flex',flexDirection:'column',gap:10}}><div style={{display:'flex',gap:10}}><span style={{color:OR,fontWeight:700}}>●</span><div><div style={{fontWeight:600}}>Pickup · 3 min</div><div style={{fontSize:13,color:mut}}>Memorial Stadium Lot 5</div></div></div><div style={{display:'flex',gap:10}}><span style={{color:PU,fontWeight:700}}>■</span><div><div style={{fontWeight:600}}>Dropoff · 18 min</div><div style={{fontSize:13,color:mut}}>GSP Airport · Terminal</div></div></div></div><div style={{display:'flex',alignItems:'center',gap:10,margin:'16px 0'}}><div style={{width:40,height:40,borderRadius:'50%',background:'#FFF4EC',display:'grid',placeItems:'center',fontWeight:700,color:OR}}>J</div><div><div style={{fontWeight:600}}>John</div><div style={{fontSize:13,color:mut}}>★ 4.97</div></div></div><Btn v="p" onClick={()=>{setOffer(false);alert('Accepted — stub')}}>Accept</Btn><button onClick={()=>setOffer(false)} style={{width:'100%',marginTop:10,padding:12,fontWeight:600,color:mut}}>Decline</button></div>}</div>}
function Stub({title,body,tab}){return <div style={{display:'flex',flexDirection:'column',minHeight:'100%'}}><div style={{flex:1,padding:24}}><button onClick={()=>nav('home')} style={{fontSize:20,marginBottom:12}}>←</button><h1 style={{fontSize:24,fontWeight:600}}>{title}</h1><p style={{color:mut,marginTop:8,lineHeight:1.4}}>{body}</p>{tab==='account'&&<button onClick={()=>nav('driver')} style={{marginTop:14,fontWeight:600,color:PU}}>Switch to driver mode →</button>}</div><Tabs a={tab} on={id=>nav(id==='home'?'home':id)}/></div>}
function Screen(){const[{path,params},setR]=useState(route);useEffect(()=>{const h=()=>setR(route());addEventListener('hashchange',h);return()=>removeEventListener('hashchange',h)},[]);switch(path){case'landing':case'':return <Landing/>;case'home':case'rides':return <Home/>;case'confirm':return <Confirm dest={params.dest||'GSP Airport'}/>;case'tiers':return <Tiers dest={params.dest||'1900 GSP Dr'}/>;case'schedule':return <Schedule/>;case'driver':return <Driver/>;case'friends':return <Stub title="Ride with friends" body="Split fares and share ETAs. Stubbed for Phase B." tab="friends"/>;case'account':return <Stub title="Account" body="Welcome, John · Tiger rider. Auth stubbed." tab="account"/>;default:return <Landing/>}}
export default function App(){return <div className="desktop-frame"><div className="app-shell"><Screen/></div></div>}

