  --success: #1F8A4C;
  --danger: #D92D20;
  --shadow-soft: 0 8px 28px rgba(11, 18, 32, 0.10);
  --shadow-pill: 0 2px 8px rgba(11, 18, 32, 0.08);
  --radius-sheet: 24px;
  --radius-card: 18px;
  --radius-pill: 999px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html, body, #root {
  height: 100%;
  font-family: var(--font);
  color: var(--ink);
  background: var(--surface-muted);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}
a { color: inherit; text-decoration: none; }
input, textarea {
  font-family: inherit;
  font-size: 16px;
}
.app-shell {
  min-height: 100%;
  max-width: 480px;
  margin: 0 auto;
  background: var(--surface-muted);
  position: relative;
  box-shadow: 0 0 60px rgba(11, 18, 32, 0.08);
}
.desktop-frame {
  min-height: 100vh;
  background: linear-gradient(160deg, #1a0f2e 0%, #2d1b4e 40%, #1a1208 100%);
  padding: 24px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}
@media (min-width: 900px) {
  .desktop-frame {
    flex-direction: row;
    justify-content: center;
    align-items: flex-start;
    gap: 32px;
    padding: 40px;
  }
  .app-shell {
    min-height: calc(100vh - 80px);
    height: calc(100vh - 80px);
    overflow: hidden;
    border-radius: 28px;
    border: 1px solid rgba(255,255,255,0.08);
  }
}
.pressable:active { transform: scale(0.98); }
.fade-in {
  animation: fadeIn 280ms ease-out;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes modalIn {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}
@keyframes sheetUp {
  from { transform: translateY(24px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
